-- Part 23.15: the inter-company accounts, the flag, the pages, the page tracker and the notification templates.
INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
  SELECT NULL, a.group_id, '160090', 'Inter-company receivable (due from group companies)', 'GENERAL', 'DR', 'INR', 0, NULL, 0, 'migration', 'fin_p2315' FROM fin_accounts a WHERE a.company_id IS NULL AND a.code = '160001' AND a.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM fin_accounts x WHERE x.company_id IS NULL AND x.code = '160090');
